import{_ as t,o as a,c as r,ak as i}from"./chunks/framework.B8jO0odJ.js";const p=JSON.parse('{"title":"AI lesson source research: 13 terms","description":"This source research began October 28, 2026 for learners ages 12–17 and was reconciled with the confirmed design on November 11.\\nThe current GDD requires all 13 AI lessons, th","frontmatter":{"title":"AI lesson source research: 13 terms","description":"This source research began October 28, 2026 for learners ages 12–17 and was reconciled with the confirmed design on November 11.\\nThe current GDD requires all 13 AI lessons, th","source":"docs/planning/ai-source-research.md","category":"Learning content","sourceUpdated":"2026-11-11T12:24:37+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/planning/ai-source-research.md","filePath":"content/docs/planning/ai-source-research.md"}'),s={name:"content/docs/planning/ai-source-research.md"};function n(o,e,d,l,c,h){return a(),r("div",null,[...e[0]||(e[0]=[i('<div><h1 id="ai-lesson-source-research-13-terms">AI lesson source research: 13 terms<a class="header-anchor" href="#ai-lesson-source-research-13-terms" aria-label="Link to this section">​</a></h1><p>This source research began October 28, 2026 for learners ages 12–17 and was reconciled with the confirmed design on November 11. The <a href="/Chainy-Docs/content/docs/game-design-lesson-collection.html">current GDD</a> requires all 13 AI lessons, three distinct activities, and 13 review questions with correction retries. AI is a required world after Blockchain; its activities may use clearly labeled offline teaching simulations, without actual model training. These are <strong>13 distinct A–Z letters</strong>, not chapters from an existing AI encyclopedia. The source definitions support Sean&#39;s authored copy; they do not establish school approval, validated learning outcomes, or implemented features. The former conditional A01–A03 classifier and later A04–A05 proposal belongs to the <a href="/Chainy-Docs/content/docs/planning/quest-curriculum.html">historical quest curriculum</a>. Current work is documentation and preparation only; final owner approval is required before Unity development.</p><h2 id="source-hierarchy">Source hierarchy<a class="header-anchor" href="#source-hierarchy" aria-label="Link to this section">​</a></h2><ul><li><a href="https://www.unesco.org/en/articles/ai-competency-framework-students">UNESCO, <em>AI Competency Framework for Students</em> (2024)</a>: age-relevant curriculum framework covering human agency, ethics, AI techniques, and system design. Use for learning goals, not as proof of school approval.</li><li><a href="https://ai4k12.org/gradeband-progression-charts/">AI4K12, Five Big Ideas in AI</a>: K–12 framing for perception, representation and reasoning, learning, natural interaction, and societal impact. Its 6–8 and 9–12 bands help check level of explanation. It is a framework, not an A–Z encyclopedia.</li><li><a href="https://developers.google.com/machine-learning/glossary/">Google for Developers, Machine Learning Glossary</a> and <a href="https://developers.google.com/machine-learning/intro-to-ml/what-is-ml">Introduction to Machine Learning</a>: first-party technical definitions and examples. Adapt wording for teens; avoid copying long passages.</li><li><a href="https://oecd.ai/en/wonk/definition">OECD.AI, updated AI system definition</a>: broad AI definition that includes predictions, content, recommendations, and decisions. It helps distinguish AI from the game&#39;s scripted dialogue.</li><li><a href="https://airc.nist.gov/airmf-resources/airmf/3-sec-characteristics/">NIST AI Risk Management Framework, trustworthy characteristics</a>: fairness, reliability, privacy, explainability, and accountability. Use for limits and responsible use, not as a game certification.</li></ul><h2 id="term-to-source-map">Term-to-source map<a class="header-anchor" href="#term-to-source-map" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Letter</th><th>Term</th><th>Teen-level lesson point</th><th>Direct source</th><th>Suggested treatment</th></tr></thead><tbody><tr><td>A</td><td>Artificial intelligence</td><td>An AI system uses inputs to produce predictions, content, recommendations, or decisions for a task.</td><td><a href="https://oecd.ai/en/wonk/definition">OECD.AI definition</a></td><td>Quiz: identify an AI task versus a fixed rule.</td></tr><tr><td>B</td><td>Bias</td><td>The selection and labeling of examples can skew a model&#39;s results; investigate who or what is missing.</td><td><a href="https://developers.google.com/machine-learning/crash-course/fairness/types-of-bias">Google, types of bias</a></td><td>Quiz with visibly uneven fictional examples.</td></tr><tr><td>C</td><td>Classification</td><td>A classifier predicts a category, such as Routine or Review, from supplied features.</td><td><a href="https://developers.google.com/machine-learning/intro-to-ml/what-is-ml">Google, what is ML?</a></td><td>Collect the category-output panel; review the fictional prediction example.</td></tr><tr><td>D</td><td>Dataset</td><td>A dataset is a collection of examples; its coverage and quality affect what a model can learn.</td><td><a href="https://developers.google.com/machine-learning/crash-course/overfitting/data-characteristics">Google, data characteristics</a> and <a href="https://developers.google.com/machine-learning/guides/data-traps/quality">data quality</a></td><td>Quiz: identify a missing kind of example.</td></tr><tr><td>F</td><td>Feature</td><td>A feature is an input detail used to make a prediction; choose details that bear on the task.</td><td><a href="https://developers.google.com/machine-learning/intro-to-ml/supervised">Google, supervised learning</a></td><td>Collect the annotated example display; review relevant details.</td></tr><tr><td>G</td><td>Generative AI</td><td>Generative models can create text, images, or other content; outputs need checking.</td><td><a href="https://developers.google.com/machine-learning/intro-to-ml/what-is-ml">Google, what is ML?</a> and <a href="https://developers.google.com/machine-learning/glossary/generative">generative glossary</a></td><td>Fact Patch: compare authored text with a trusted reference; no live model required.</td></tr><tr><td>H</td><td>Human oversight</td><td>A person checks evidence and keeps control of consequential actions assisted by AI.</td><td><a href="https://www.unesco.org/en/articles/ai-competency-framework-students">UNESCO student framework</a> and <a href="https://unesdoc.unesco.org/in/rest/annotationSVC/DownloadWatermarkedAttachment/attach_import_54aee321-6000-4d79-9e2b-c99743e52590?_=391105eng.pdf&amp;from=1&amp;to=80">UNESCO chapter 4</a></td><td>Collect the human-review terminal explanation; review when a person must pause a suggested action.</td></tr><tr><td>L</td><td>Label</td><td>A label is the known answer attached to a training example.</td><td><a href="https://developers.google.com/machine-learning/intro-to-ml/supervised">Google, supervised learning</a></td><td>Label Lab: label fictional request cards from verified evidence.</td></tr><tr><td>M</td><td>Model</td><td>A trained model uses learned relationships to produce a prediction for a new input.</td><td><a href="https://developers.google.com/machine-learning/intro-to-ml/what-is-ml">Google, what is ML?</a> and <a href="https://developers.google.com/machine-learning/glossary/fundamentals">ML glossary</a></td><td>Quiz: distinguish a learned model from a hard-coded answer list.</td></tr><tr><td>P</td><td>Prediction</td><td>A prediction is the model&#39;s proposed output; it can be wrong.</td><td><a href="https://developers.google.com/machine-learning/intro-to-ml/supervised">Google, supervised learning</a></td><td>Quiz: compare prediction with later verified answer.</td></tr><tr><td>R</td><td>Responsible AI</td><td>Judge whether the data, intended use, privacy, and possible harm make AI assistance appropriate.</td><td><a href="https://www.unesco.org/en/articles/ai-competency-framework-students">UNESCO student framework</a> and <a href="https://airc.nist.gov/airmf-resources/airmf/3-sec-characteristics/">NIST trustworthy characteristics</a></td><td>Quiz using a low-stakes fictional decision.</td></tr><tr><td>T</td><td>Training</td><td>During training, a model adjusts from labeled examples; this differs from merely reading a script.</td><td><a href="https://developers.google.com/machine-learning/intro-to-ml/supervised">Google, supervised learning</a></td><td>Collect the training-process illustration; distinguish real fitting from the game&#39;s simulation.</td></tr><tr><td>V</td><td>Validation</td><td>Evaluate a model on examples kept separate from its training examples; reserve fresh test items for the final check.</td><td><a href="https://developers.google.com/machine-learning/crash-course/overfitting/dividing-datasets">Google, dividing datasets</a></td><td>Test the Helper: inspect fixed fictional predictions and their mistakes on fresh cases; no model is fitted.</td></tr></tbody></table><h2 id="fit-with-the-current-game">Fit with the current game<a class="header-anchor" href="#fit-with-the-current-game" aria-label="Link to this section">​</a></h2><p>The GDD assigns Label Lab to LC-A04, Test the Helper to LC-A09, and Fact Patch to LC-A12. The other ten lessons are ordinary collectibles, and every lesson has one required review question. Authored examples can explain training, prediction, and verification without claiming that the player trained a model. A real local classifier would require example-dependent fitting and separate evaluation; it is not required by this design.</p><p>The 13-lesson scope is an owner decision, not a requirement established by these sources or the school. Educator review, reading-load checks, implementation, and named-device acceptance remain separate evidence gaps. The November 10 community session is a past scheduled event with an unverified outcome. Pre-final remains November 21, 2026; preserve integration, QA, manuscript, and rehearsal time.</p><h2 id="research-cautions">Research cautions<a class="header-anchor" href="#research-cautions" aria-label="Link to this section">​</a></h2><ul><li>The Google glossary uses <strong>bias</strong> both as a mathematical parameter and as harmful or unfair skew. The B lesson uses the second meaning; name that distinction in final copy.</li><li><strong>Validation</strong> is often an iterative development check. A fresh <strong>test set</strong> is a separate final check. The V lesson should show both without claiming that a handful of cards establishes real-world reliability.</li><li><strong>Generative AI</strong>, a trained <strong>classifier</strong>, and an <strong>agent</strong> are different behaviors. The game&#39;s authored predictions and text must remain labeled as simulations, not claimed as training or live generation.</li><li>Avoid real learner records, personal identity data, and copyrighted source artwork in lesson cards. Use fictional examples and original explanations.</li></ul></div>',1)])])}const g=t(s,[["render",n]]);export{p as __pageData,g as default};
